package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.*;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import java.util.*;import java.time.*;import java.util.concurrent.*;import java.util.function.Supplier;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa","greenocean.clinic.reputation-enabled=true","greenocean.clinic.public-reputation-enabled=true","greenocean.clinic.reputation-keys=reputation-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.reputation-current-key=reputation-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test") @org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseP5ConcurrencyTest extends PhaseP4Fixtures {
 @Autowired ClinicIntegration integration;
 static final String SCHEMA="qa_p5_race_"+UUID.randomUUID().toString().replace("-","");
 @DynamicPropertySource static void schema(DynamicPropertyRegistry p){String url=System.getenv("GREENOCEAN_TEST_DB_URL");p.add("spring.datasource.url",()->url+(url.contains("?")?"&":"?")+"currentSchema="+SCHEMA+",public");p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.jpa.properties.hibernate.default_schema",()->SCHEMA);}
 @AfterAll static void drop(@Autowired JdbcTemplate db){db.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}
 Object result(Supplier<?> run){try{return run.get();}catch(RuntimeException e){return e;}}
 List<Object> race(Supplier<?> a,Supplier<?> b)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var x=pool.submit(()->{start.await();return result(a);});var y=pool.submit(()->{start.await();return result(b);});start.countDown();return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}}

 ClinicCommerce.Booking replacement(){UUID slot=scheduling.slot(author.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(7200),Instant.now().plusSeconds(9000),"TEXT",0,"Asia/Tehran",true));commerce.offer(author.id(),slot,policy,false);return new ClinicCommerce.Booking(slot,UUID.randomUUID(),db.queryForObject("SELECT revision FROM professional_availability_slots WHERE id=?",Long.class,slot),policy,0,true);}
 @Test void concurrentReplacementRetriesCreateOneNewBooking()throws Exception{var b=replacement();var r=race(()->integration.reschedule(learner.id(),learner.session(),appointment,1,b),()->integration.reschedule(learner.id(),learner.session(),appointment,1,b));assertThat(r).allMatch(Map.class::isInstance);assertThat(((Map<?,?>)r.getFirst()).get("id")).isEqualTo(((Map<?,?>)r.getLast()).get("id"));assertThat(db.queryForObject("SELECT count(*) FROM clinic_booking_changes WHERE old_appointment_id=?",Integer.class,appointment)).isEqualTo(1);}
 @Test void failedReplacementRollsBackOldCancellation(){var b=replacement();var wrong=new ClinicCommerce.Booking(b.slotId(),b.retryKey(),b.slotRevision(),b.policyId(),1,true);assertThat(result(()->integration.reschedule(learner.id(),learner.session(),appointment,1,wrong))).isInstanceOf(RuntimeException.class);assertThat(commerce.appointment(learner.id(),appointment)).containsEntry("status","CONFIRMED");assertThat(db.queryForObject("SELECT count(*) FROM clinic_booking_changes WHERE old_appointment_id=?",Integer.class,appointment)).isZero();}
 @Test void simultaneousDistinctSubscriptionKeysCannotOverlap()throws Exception{UUID p=commerce.plan(issuer.id(),"race-"+UUID.randomUUID(),List.of("ADMIN_REPORTS"),0,7);var r=race(()->commerce.subscribe(author.id(),p,UUID.randomUUID(),true),()->commerce.subscribe(author.id(),p,UUID.randomUUID(),true));assertThat(r.stream().filter(Map.class::isInstance).count()).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM clinic_professional_subscriptions WHERE professional_id=?",Integer.class,author.id())).isEqualTo(1);}
 @Test void concurrentRightsRetriesReturnOneRequest()throws Exception{UUID retry=UUID.randomUUID();var r=race(()->integration.rights(learner.id(),learner.session(),appointment,"FINANCE","EXPORT",retry),()->integration.rights(learner.id(),learner.session(),appointment,"FINANCE","EXPORT",retry));assertThat(r).allMatch(UUID.class::isInstance);assertThat(r.getFirst()).isEqualTo(r.getLast());}
}
